function toughTopicHighlights(a){let g=toughTopicGroups(a).filter(x=>x.n>=difficultyState.minN).sort((a,b)=>b.avg-a.avg),card=(title,items,color)=>panel('',title,`At least ${difficultyState.minN} questions per family · active scope`,`<div class="panel-content">${items.map(x=>`<button class="topic-highlight" data-diff-topic="${E(x.topic)}" data-subject="${E(x.subject)}"><div><strong>${E(x.topic)}</strong><small>${E(x.subject)} · n=${x.n}</small></div><b style="color:${color}">${F(x.avg,2)}<small>/100</small></b></button>`).join('')||'<div class="empty">No family reaches the selected minimum sample.</div>'}</div>`,'','Relative content challenge. Open the questions before treating a topic as uniformly easy or tough.');return `<div class="grid-two difficulty-grid" style="margin-top:18px">${card('Higher-challenge topic families',g.slice(0,5),'#e3a1ab')}${card('Lower-challenge topic families',g.slice(-5).reverse(),'#80cdb3')}</div>`}
function toughTopicHeatPanel(a){let gs=toughTopicGroups(a).filter(g=>g.n>=difficultyState.minN).sort((a,b)=>b.n-a.n),ys=scopeYears();return '<div id="difficulty-map" style="height:18px"></div>'+panel('09','Topic × year difficulty map','Mean toughness of each topic in each selected year. n is always shown.',`<div class="table-scroll panel-content" style="max-height:650px"><table class="heat"><thead><tr><th>TOPIC / SUBJECT</th>${ys.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${gs.map(g=>`<tr><td>${E(g.topic)}<small class="heat-n">${E(g.subject)}</small></td>${ys.map(y=>{let b=g.items.filter(q=>q.year===y),v=b.length?mean(b.map(q=>q.toughness.score)):null,color=v===null?'#1c2633':v<difficultyState.easy?'rgba(91,175,151,.35)':v<difficultyState.tough?'rgba(201,159,82,.4)':'rgba(195,106,125,.6)';return `<td data-diff-topic-year="${y}" data-topic="${E(g.topic)}" data-subject="${E(g.subject)}" style="background:${color}" title="${E(g.topic)} / ${y}: ${b.length} questions">${F(v)}<small class="heat-n">n=${b.length}</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`,'','Click a cell to inspect that topic in that year. Missing cells are not zero difficulty.')}
document.addEventListener('click',e=>{let cell=e.target.closest('[data-diff-topic-year]');if(cell){$('#from').value=$('#to').value=cell.dataset.diffTopicYear;$('#subject').value=cell.dataset.subject;query=cell.dataset.topic;verdict='all';difficultyQuestionBand='all';page=0;location.hash='questions';if(view==='questions')render()}});
